/**  `package-lock.json`. */
"Npm" | 
/**  `pnpm-lock.yaml`. */
"Pnpm" | 
/**  `yarn.lock`. */
"Yarn" | 
/**  `poetry.lock`. */
"Poetry" | 
/**  `Cargo.lock`. */
"Cargo" | 
/**  `gradle.lockfile`. */
"Gradle" | 
/**  `go.sum`. */
"GoSum";

/**  One line of a running lockfile command (emitted as `lockfile-output`). */
